with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '天橋立図', '雪舟', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Sesshu_-_View_of_Ama-no-Hashidate.jpg/960px-Sesshu_-_View_of_Ama-no-Hashidate.jpg', '室町時代の画僧・雪舟が、京都府北部の名勝・天橋立を描いた水墨画で、国宝に指定され京都国立博物館が所蔵しています。高い視点から湾に延びる砂州と周辺の寺社や山並みを一望する構図で、画中には地名が書き込まれています。何枚もの紙を継いで描かれていることから、本画のための下絵とも考えられています。中国の山水画を学んだ雪舟が、日本の実景を自分の目でとらえて描いた点に見どころがあります。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Sesshu_-_View_of_Ama-no-Hashidate.jpg'),
    (2, '第九の波', 'イヴァン・アイヴァゾフスキー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg/960px-Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg', 'ロシアの海洋画家イヴァン・アイヴァゾフスキーが1850年に描いた代表作で、サンクトペテルブルクのロシア美術館が所蔵しています。嵐の夜が明けた海で、難破した船のマストにしがみつく人々に、巨大な波が迫ります。題名は、嵐の中で最も大きいとされる「九番目の波」の言い伝えに由来します。透けるような緑の波と、雲間から差す金色の光の対比が、絶望の中の希望を感じさせます。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('ヴェネチア・ビエンナーレ芸術監督にアル・カシミ', '2028年の第62回ヴェネチア・ビエンナーレ国際美術展の芸術監督に、「あいち2025」を手がけたフール・アル・カシミが就任する。', 'ヴェネチア・ビエンナーレは11月26日、2028年に開催される第62回ヴェネチア・ビエンナーレ国際美術展のアーティスティック・ディレクターに、フール・アル・カシミが就任すると発表した。会期は2028年4月8日から11月26日まで。アル・カシミは長年シャルジャ・ビエンナーレのディレクターを務め、2009年にはシャルジャ美術財団を設立した。日本では国際芸術祭「あいち2025」の芸術監督を務め、2026年の第25回シドニー・ビエンナーレでも芸術監督を担った。草間彌生やウィリアム・ケントリッジらの個展も手がけてきた。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/headline/33388',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('ポーラ美術館、25周年記念展「リフレクション」', '箱根のポーラ美術館で2027年4月27日から、開館25周年記念企画展の第2弾「リフレクション」が開かれる。', '神奈川県箱根町のポーラ美術館で、開館25周年記念企画展の第2弾「リフレクション―アートは世界を映しだす：印象派から現代美術」が開催される。会期は2027年4月27日から11月25日まで。アーティストが環境や社会、自らの内面と向き合って作品に映しだした世界と、鑑賞者の心とのあいだに生まれる関係に焦点を当てる。初公開の新収蔵作品を含む同館のコレクションを中心に、約20名の作家による絵画やインスタレーション、映像などが並ぶ。出展作家にはゴッホ、ルイーズ・ブルジョワ、ゲルハルト・リヒターらが名を連ねる。同時に「HIRAKU Project Vol.18 大和田俊」も開催される。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33390',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
