values ('ポントワーズ、エルミタージュの森のはずれ', 'Edge of the Woods Near L''Hermitage, Pontoise', 'カミーユ・ピサロ', 'Camille Pissarro',
        1879,
        (select slug from public.art_movements where slug = 'impressionism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1951.356/1951.356_web.jpg', 'ピサロが1872年から暮らしたポントワーズ近郊の村エルミタージュの森を描いた大作です。木漏れ日の差す林で人物がまどろみ、その傍らには後ろ姿のヤギが立っています。純色に絞った絵具を規則的な斜めの筆致で重ねる描き方を、ピサロ自身は編み物にたとえました。生活に困窮し、作品が売れなかった時期の制作で、1879年の第4回印象派展に出品されました。コローらの風景画を受け継ぎつつ、筆触の積み重ねで画面を組み立てる姿勢は、ポントワーズでともに制作したセザンヌにも影響を与えました。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1951.356')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

