insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('牧谿', 'Muqi', '牧谿',
        null, null, 'east_asia', array['song-yuan']::text[],
        '南宋末から元初めの禅僧画家で、日本の水墨画に大きな影響を与えた。', '13世紀後半、中国の南宋末から元の初めにかけて活動した禅僧で、法諱は法常、牧谿は号です。生没年はわかっていません。崇慶府の出身とされ、禅僧・無準師範の門下に入ったと伝えられます。都の臨安にあった西湖のほとりの六通寺に住み、制作しました。

湿り気を帯びた大気を感じさせる独特の水墨表現で知られますが、中国では元代に「粗放で古法がない」と評され、しだいに忘れられていきました。一方、日本には鎌倉時代末の14世紀初めには作品が伝わり、14世紀中頃には贋作が多く作られるほどの人気を集めました。

大徳寺の「観音猿鶴図」（国宝）や、足利義満が掛物に改装した「瀟湘八景図巻」の断簡が代表作です。室町時代の水墨画に多くの追随者を生み、なかでも長谷川等伯は牧谿を熱心に学び、「松林図屏風」にその成果が表れています。現在、牧谿の優品のほとんどは日本にあります。', 'https://ja.wikipedia.org/wiki/%E7%89%A7%E8%B0%BF')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アーシル・ゴーキー', 'Arshile Gorky', 'ゴーキー',
        1904, 1948, 'west', array['abstract-expressionism', 'surrealism']::text[],
        'アルメニア出身で、抽象表現主義への道を開いたアメリカの画家。', '1904年、オスマン帝国領のヴァン近くに生まれたアルメニア人の画家で、本名はヴォスダニック・マヌーク・アドヤンです。1915年のアルメニア人虐殺のなかで母を失い、1920年に先に渡っていた父を頼ってアメリカへ移りました。1922年にボストンの美術学校に入り、教える仕事もしながら、はじめは印象派から強い影響を受けました。

やがて、生き物を思わせる有機的な形がうごめき、叩きつけた絵具が流れ落ちるままにされた画面を生み出します。そこにはシュルレアリスムのオートマティスム（自動書記）の影響が見られますが、勢いに任せたように見える画面は、実は綿密な計画とデッサンにもとづいていました。

代表作に「芸術家と母親」（ホイットニー美術館）や「花咲く水車小屋の水」（メトロポリタン美術館）があります。1948年に44歳で亡くなりましたが、その画面は抽象表現主義へとつながる道を開きました。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%BC%E3%82%B7%E3%83%AB%E3%83%BB%E3%82%B4%E3%83%BC%E3%82%AD%E3%83%BC')
on conflict (name) do update set
